export default function Experience() {
    return (
        <>
            {EXPERIENCES.map((entry, idx) => {
                if (entry.divider) {
                    return <Divider key={`divider-${idx}`}>{entry.divider}</Divider>
                }

                const text = (
                    <TextBlock $align={entry.align}>
                        <OrgName>{entry.org}</OrgName>
                        <Role>{entry.role}</Role>
                        {entry.summary && <Summary>{entry.summary}</Summary>}
                        <Period>{entry.period}</Period>
                    </TextBlock>
                )
                const image =
                    entry.align === 'right' ? (
                        <LogoRight
                            src={entry.logo}
                            alt={entry.alt}
                            height={entry.logoHeight}
                            loading="lazy"
                        />
                    ) : (
                        <LogoLeft
                            src={entry.logo}
                            alt={entry.alt}
                            height={entry.logoHeight}
                            loading="lazy"
                        />
                    )

                return (
                    <Entry key={idx} $align={entry.align}>
                        {entry.align === 'right' ? (
                            <>
                                {text}
                                {image}
                            </>
                        ) : (
                            <>
                                {image}
                                {text}
                            </>
                        )}
                    </Entry>
                )
            })}
        </>
    )
}
